import json,glob,re,os
def extract(t):
    t=t.strip()
    i=t.find('{')
    if i<0: return None
    depth=0
    for k in range(i,len(t)):
        if t[k]=='{': depth+=1
        elif t[k]=='}':
            depth-=1
            if depth==0:
                try: return json.loads(t[i:k+1])
                except Exception as e: return {'_err':str(e),'raw':t[i:k+1]}
    return None
for f in sorted(glob.glob('/workspace/scratch/out/*.json')):
    d=json.load(open(f))
